begin;
select plan(40);

select has_function('public','attest_final_window',array['uuid','uuid','bigint','text','bigint[]'],'attestation RPC exists');
select has_function('public','finalize_competition',array['uuid'],'service finalizer RPC exists');
select has_column('public','participant_finalization_attestations','semantic_event_id','attestations have semantic identity');
select has_column('public','participant_finalization_attestations','attestation_version','attestations are append-only versioned');
select ok(exists(select 1 from pg_constraint where conname='participant_attestation_version_unique'),'attestation versions are unique per owner');
select ok(exists(select 1 from pg_proc join pg_namespace on pg_namespace.oid=pg_proc.pronamespace where nspname='private' and proname='owner_window_commitment_v1'),'window commitment exists');
select ok(exists(select 1 from pg_proc join pg_namespace on pg_namespace.oid=pg_proc.pronamespace where nspname='private' and proname='result_immutable_hash_v1'),'result hash exists');
select ok(not has_function_privilege('anon','public.attest_final_window(uuid,uuid,bigint,text,bigint[])','EXECUTE'),'anon cannot attest');
select ok(not has_function_privilege('authenticated','public.finalize_competition(uuid)','EXECUTE'),'users cannot scheduled-finalize');
select ok(has_function_privilege('service_role','public.finalize_competition(uuid)','EXECUTE'),'service may finalize');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('71000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','final-a@example.invalid','',now(),now()),
('71000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','final-b@example.invalid','',now(),now());
insert into public.profiles(id,auth_user_id,display_name,state) values
('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','A','active'),
('72000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002','B','active');
insert into public.competitions(id,creator_profile_id,time_zone_identifier,start_day,scoring_policy_identity,lifecycle,invitation_expires_at,best_available_deadline) values
('73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','UTC','2026-08-01','healthcomp.activity-score.v1','tallying','2026-07-31','2099-01-01'),
('73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','UTC','2026-08-12','healthcomp.activity-score.v1','tallying','2026-08-01','2026-08-10'),
('73000000-0000-0000-0000-000000000003','72000000-0000-0000-0000-000000000001','UTC','2026-08-12','healthcomp.activity-score.v1','tallying','2026-08-11','2099-01-01');
insert into public.competition_participants(competition_id,profile_id,role,state)
select c.id,p.id,case when p.id='72000000-0000-0000-0000-000000000001' then 'creator' else 'invitee' end,'accepted'
from (values('73000000-0000-0000-0000-000000000001'::uuid),('73000000-0000-0000-0000-000000000002'::uuid),('73000000-0000-0000-0000-000000000003'::uuid)) c(id)
cross join (values('72000000-0000-0000-0000-000000000001'::uuid),('72000000-0000-0000-0000-000000000002'::uuid)) p(id);
insert into public.daily_score_revisions(competition_id,participant_profile_id,day_ordinal,semantic_event_id,client_revision,move_mode,stand_mode,move_basis_points,exercise_basis_points,stand_basis_points,accepted_centi_points,availability_reason,scoring_policy_identity,wire_content_sha256,server_seq,evaluated_at)
select '73000000-0000-0000-0000-000000000001',p.id,d,gen_random_uuid()::text,d,'activeEnergyKilocalories','standHours',
 case when p.id='72000000-0000-0000-0000-000000000001' then 300 else 100 end,200,100,
 case when p.id='72000000-0000-0000-0000-000000000001' then 600 else 400 end,'available','healthcomp.activity-score.v1',
 private.wire_score_digest_v1('73000000-0000-0000-0000-000000000001',p.id,d::smallint,'activeEnergyKilocalories','standHours',case when p.id='72000000-0000-0000-0000-000000000001' then 300 else 100 end,200,100,case when p.id='72000000-0000-0000-0000-000000000001' then 600 else 400 end,'available','healthcomp.activity-score.v1',d),1,'2026-07-31'::timestamptz+d*interval '1 day'
from (values('72000000-0000-0000-0000-000000000001'::uuid),('72000000-0000-0000-0000-000000000002'::uuid)) p(id) cross join generate_series(1,7) d;
insert into public.daily_score_revisions(competition_id,participant_profile_id,day_ordinal,semantic_event_id,client_revision,move_mode,stand_mode,move_basis_points,exercise_basis_points,stand_basis_points,accepted_centi_points,availability_reason,scoring_policy_identity,wire_content_sha256,server_seq,evaluated_at)
select '73000000-0000-0000-0000-000000000003',p.id,d,gen_random_uuid()::text,d,'activeEnergyKilocalories','standHours',100,100,100,300,'available','healthcomp.activity-score.v1',private.wire_score_digest_v1('73000000-0000-0000-0000-000000000003',p.id,d::smallint,'activeEnergyKilocalories','standHours',100,100,100,300,'available','healthcomp.activity-score.v1',d),1,'2026-08-11'::timestamptz+d*interval '1 day'
from (values('72000000-0000-0000-0000-000000000001'::uuid),('72000000-0000-0000-0000-000000000002'::uuid)) p(id) cross join generate_series(1,7) d;

select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.attest_final_window('73000000-0000-0000-0000-000000000003','74000000-0000-4000-8000-000000000003',1,'stable',array[1,2,3,4,5,6,7]::bigint[])$$,'P0001','window_not_stable','stable attestation rejects before the local Day-8 boundary');
select is(public.attest_final_window('73000000-0000-0000-0000-000000000001','74000000-0000-4000-8000-000000000001',1,'stable',array[1,2,3,4,5,6,7]::bigint[])->>'disposition','appended','first stable attestation appends');
select throws_ok($$select public.attest_final_window('73000000-0000-0000-0000-000000000001','74000000-0000-4000-8000-000000000001',1,'stable',array[1,2,3,4,5,6,7]::bigint[],repeat('0',64))$$,'22023','window_commitment_mismatch','expected owner commitment is verified even for an exact duplicate');
select throws_ok($$select public.attest_final_window('73000000-0000-0000-0000-000000000001','74000000-0000-4000-8000-000000000004',2,'best_available',array[1,2,3,4,5,6,7]::bigint[])$$,'P0001','attestation_downgrade','stable attestation cannot downgrade to best available');
select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is(public.attest_final_window('73000000-0000-0000-0000-000000000001','74000000-0000-4000-8000-000000000002',1,'stable',array[1,2,3,4,5,6,7]::bigint[])->>'disposition','appended','second current stable attestation converges');
select is((select frozen_window->>'version' from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'2','stable finalizer emits rich v2 projection');
select is((select finalization_basis from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'stable','both current stable attestations win');
select is((select count(*)::int from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),1,'stable finalization creates one result');
select is((select count(*)::int from public.competition_awards where competition_id='73000000-0000-0000-0000-000000000001'),1,'winner receives one award');
select is(public.submit_score_revision('73000000-0000-0000-0000-000000000001',(select semantic_event_id::uuid from public.daily_score_revisions where competition_id='73000000-0000-0000-0000-000000000001' and participant_profile_id='72000000-0000-0000-0000-000000000002' and day_ordinal=1),1,1,'2026-08-01T00:00:00Z','activeEnergyKilocalories','standHours',100,200,100,'available','healthcomp.activity-score.v1')->>'disposition','duplicate','exact duplicate remains idempotent after finalization');

select set_config('request.jwt.claims','{"sub":"71000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(public.submit_score_revision('73000000-0000-0000-0000-000000000002','75000000-0000-4000-8000-000000000001',1,1,'2026-08-12T00:00:00Z','activeEnergyKilocalories','standHours',0,0,0,'available','healthcomp.activity-score.v1',repeat('0',64))->>'code','competition_finalized','deadline score path returns typed rejection without rolling back finalization');
select is((select count(*)::int from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),1,'opportunistic deadline finalization persists');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.finalize_competition('73000000-0000-0000-0000-000000000002')->>'disposition','existing','scheduled finalizer converges with opportunistic result');
select is((select finalization_basis from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'best_available','deadline uses best-available basis');
select is((select count(*)::int from public.competition_results r cross join lateral jsonb_array_elements(r.frozen_window->'participants') p cross join lateral jsonb_array_elements(p->'days') d where r.competition_id='73000000-0000-0000-0000-000000000002' and d->>'source'='deadline_missing'),14,'deadline projection explicitly synthesizes fourteen missing days');
select is(public.finalize_competition('73000000-0000-0000-0000-000000000002')->>'disposition','existing','deadline finalization is idempotent');
select is((select count(*)::int from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),1,'repeated finalizer keeps one result');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,extra}','true') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator rejects recursive extra keys');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,source}','"accepted_revision"') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator rejects invalid source and null-field combination');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,window_commitment_sha256}',to_jsonb(repeat('0',64))) from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator binds participant commitment to exact days');
select isnt(private.result_immutable_hash_v1('73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001',0,decode(repeat('1',64),'hex'),'72000000-0000-0000-0000-000000000002',0,decode(repeat('2',64),'hex'),'tie',null,'best_available'),private.result_immutable_hash_v1('73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001',1,decode(repeat('1',64),'hex'),'72000000-0000-0000-0000-000000000002',0,decode(repeat('2',64),'hex'),'winner','72000000-0000-0000-0000-000000000001','best_available'),'result hash changes with totals and outcome');
select is(encode(private.owner_window_commitment_v1('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',array[0,0,0,0,0,0,0]::bigint[]),'hex'),'ac2f2c82bc12949cbdc3a8e6f70f1d8bb1eb6c2a3eb0b12b7ae1be50e8e9cea3','PostgreSQL owner-window commitment matches the sole fixture golden');
select is(encode(private.result_immutable_hash_v1('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',0,decode('ac2f2c82bc12949cbdc3a8e6f70f1d8bb1eb6c2a3eb0b12b7ae1be50e8e9cea3','hex'),'00000000-0000-0000-0000-000000000003',0,decode('588ea277c08636f5bbe674af648daeb482219af27bddf0c5eccf0017ee67b3de','hex'),'tie',null,'best_available'),'hex'),'3013a48c4f2de0a28b34ba9c43a456893963c21a74ab2ef9ffffa452571ef78c','PostgreSQL result hash matches the sole fixture golden');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{version}','"2"') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator rejects stringified version');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,ordinal}','"1"') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator rejects stringified ordinal');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(frozen_window,'{participants,0,days,0,source}','"accepted_revision"'),'{participants,0,days,0,reason}','"invented"'),'{participants,0,days,0,wire_content_sha256}',to_jsonb(repeat('1',64))),'{participants,0,days,0,client_revision}','"1"'),'{participants,0,days,0,server_seq}','"1"'),'{participants,0,days,0,scoring_policy_identity}','"healthcomp.activity-score.v1"') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000002'),'73000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',0,0),'v2 validator rejects open unavailable reasons');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,wire_content_sha256}',to_jsonb(('1111111111111111111111111111111111111111111111111111111111111111')::numeric)) from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',4200,2800),'v2 validator rejects numeric accepted digest');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,client_revision}','1') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',4200,2800),'v2 validator rejects numeric accepted client revision');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,server_seq}','1') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',4200,2800),'v2 validator rejects numeric accepted server sequence');
select ok(not private.is_valid_frozen_window_v2((select jsonb_set(frozen_window,'{participants,0,days,0,scoring_policy_identity}','1') from public.competition_results where competition_id='73000000-0000-0000-0000-000000000001'),'73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002',4200,2800),'v2 validator rejects numeric accepted policy identity');

select * from finish();
rollback;
